<script setup lang="ts">
import { ref, reactive, computed, onMounted } from 'vue';
import { useI18n } from 'vue-i18n';
import { request, session } from '../crm-api';
import ProductManager from '../components/ProductManager.vue';
interface Line {product_id:number|'';width:number|string;height:number|string;unit:string;material:string;color:string;control:string;quantity:number;unit_price:number|string;amount?:string;product?:{name_zh:string;name_en:string}}
interface Version {quote_id:number;version:number;inquiry_id:number;locale:string;currency:string;valid_until:string;discount:number|string;shipping:number|string;tax:number|string;terms:string;lines:Line[];total:string;subtotal:string;accepted_order_id:number|null}
interface Inquiry {id:number;customer_id?:number;company:string;contact_name:string;channel:string;locale:string;status:string;notes:string;product_id?:number|null;quantity?:number|null;width?:number|null;height?:number|null;unit?:string|null;expected_date?:string;followups:{id:number;note:string;next_at:string;created_at:string}[]}
interface Quote {id:number;inquiry_id:number;versions:Version[]}
interface Order {id:number;status:string;snapshot:Version&{customer:{company:string;contact_name:string};confirmation_note:string};history:{old_status:string;new_status:string;created_at:string;note:string}[]}
interface Customer {id:number;company:string;locale:string;notes:string;contacts:{id:number;name:string;channel:string}[];inquiries:{id:number;status:string;contact_name:string;created_at:string}[];orders:{id:number;status:string;created_at:string}[]}
const {locale}=useI18n();const tx=(z:string,e:string)=>locale.value==='zh'?z:e;
const signed=ref(!!session.token),busy=ref(false),error=ref(''),message=ref(''),tab=ref('inquiries');
const credentials=reactive({username:'',password:''});const inquiries=ref<Inquiry[]>([]),quotes=ref<Quote[]>([]),orders=ref<Order[]>([]),customers=ref<Customer[]>([]),products=ref<{id:number;name_zh:string;name_en:string;description_zh?:string;description_en?:string;sample?:boolean}[]>([]);
const selected=ref<Inquiry|null>(null),quote=ref<Quote|null>(null),version=ref<Version|null>(null),order=ref<Order|null>(null),customer=ref<Customer|null>(null),catalog=ref<number|null>(null);
const confirmationOpen=ref(false);
const note=ref(''),nextAt=ref(''),confirmation=ref(''),editing=ref(false),quoteStep=ref(1),revision=ref<number|null>(null),assisted=ref(false),draftGaps=ref<string[]>([]),customerQuery=ref('');
const profile=reactive({company:'',contact_id:0,contact_name:'',channel:'',locale:'en',notes:''});
const me=ref({username:'dylan',name:'Dylan',role:'admin'});
const passwordOpen=ref(false);
const passwordForm=reactive({current:'',next:'',confirm:''});
const users=ref<{username:string;name:string;role:string;active:number}[]>([]);
const newUser=reactive({username:'',name:'',password:'',role:'staff'});
const visibleCustomers=computed(()=>{const q=customerQuery.value.trim().toLowerCase();if(!q)return customers.value;return customers.value.filter(c=>[c.company,c.notes,...c.contacts.flatMap(p=>[p.name,p.channel])].filter(Boolean).join('\n').toLowerCase().includes(q))});
const pageSize=5;const listPage=reactive({customers:1,inquiries:1,quotes:1,orders:1});
function pageCount(n:number){return Math.max(1,Math.ceil(n/pageSize))}
function rows<T>(items:T[],key:'customers'|'inquiries'|'quotes'|'orders'){const page=Math.min(listPage[key],pageCount(items.length));return items.slice((page-1)*pageSize,page*pageSize)}
const fresh=():Line=>({product_id:1,width:1000,height:1500,unit:'mm',material:'Aluminium',color:'White',control:'Manual',quantity:1,unit_price:100});
const draft=reactive({inquiry_id:0,locale:'en',currency:'NZD',valid_until:new Date(Date.now()+30*86400000).toISOString().slice(0,10),discount:0,shipping:0,tax:0,terms:'Demonstration prices. Confirm commercial terms.',lines:[fresh()]});
const total=computed(()=>draft.lines.reduce((s,l)=>s+Number(l.quantity)*Number(l.unit_price),0)-Number(draft.discount)+Number(draft.shipping)+Number(draft.tax));
const labels:Record<string,[string,string]>={new:['新询价','New'],contacted:['已联系','Contacted'],quoted:['已报价','Quoted'],won:['赢单','Won'],confirmed:['已确认','Confirmed'],production:['生产中','In production'],ready:['待发货','Ready to ship'],delivered:['已交付','Delivered']};const status=(s:string)=>labels[s]?tx(...labels[s]):s;
async function act(fn:()=>Promise<void>){busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e);if(!session.token)signed.value=false}finally{busy.value=false}}
async function load(){const [i,p,q,o,cu,who]=await Promise.all([request<Inquiry[]>('inquiries'),request<typeof products.value>('products'),request<Quote[]>('quotes'),request<Order[]>('orders'),request<Customer[]>('customers'),request<{username:string;name:string;role:string}>('auth/me')]);inquiries.value=i;products.value=p;quotes.value=q;orders.value=o;customers.value=cu;me.value=who;if(who.role==='admin')users.value=await request('users');if(selected.value)selected.value=i.find(x=>x.id===selected.value?.id)||null;if(quote.value)quote.value=q.find(x=>x.id===quote.value?.id)||null;if(order.value)order.value=o.find(x=>x.id===order.value?.id)||null;if(customer.value)customer.value=cu.find(x=>x.id===customer.value?.id)||null;ensureSelection()}
function toggleLocale(){const next=locale.value==='zh'?'en':'zh';locale.value=next;localStorage.setItem('vera-locale',next);document.documentElement.lang=next==='zh'?'zh':'en'}
async function changePassword(){if(passwordForm.next!==passwordForm.confirm){error.value=tx('两次新密码不一致','The new passwords do not match');return}await act(async()=>{await request('auth/password',{current:passwordForm.current,new:passwordForm.next});session.token='';signed.value=false;selected.value=null;passwordForm.current='';passwordForm.next='';passwordForm.confirm='';passwordOpen.value=false;message.value=tx('密码已更新，请用新密码重新登录','Password updated. Sign in again with the new password')})}
async function addUser(){await act(async()=>{await request('users',{...newUser});newUser.username='';newUser.name='';newUser.password='';await load();message.value=tx('用户已添加','User added')})}
async function setRole(username:string,role:string){await act(async()=>{await request(`users/${username}/role`,{role});await load();message.value=tx('权限已更新','Access updated')})}
function onRole(username:string,event:Event){void setRole(username,(event.target as HTMLSelectElement).value)}
async function login(){await act(async()=>{const r=await request<{token:string}>('auth/login',credentials);session.token=r.token;signed.value=true;credentials.password='';await load()})}
async function logout(){await act(async()=>{await request('auth/logout',{});session.token='';signed.value=false;selected.value=null;quote.value=null;version.value=null;order.value=null;customer.value=null})}
async function follow(){await act(async()=>{await request('followups',{inquiry_id:selected.value!.id,note:note.value,next_at:nextAt.value});note.value='';nextAt.value='';await load();message.value=tx('跟进已保存','Follow-up saved')})}
function openCustomer(c:Customer){customer.value=c;profile.company=c.company;profile.contact_id=c.contacts[0]?.id||0;profile.contact_name=c.contacts[0]?.name||'';profile.channel=c.contacts[0]?.channel||'';profile.locale=c.locale==='zh'?'zh':'en';profile.notes=c.notes||''}
async function saveCustomer(){await act(async()=>{const id=customer.value!.id;await request(`customers/${id}`,profile);await load();message.value=tx('客户资料已保存','Customer details updated')})}
const stages=['confirmed','production','ready','delivered'];
function stageTime(step:string){return order.value?.history.filter(h=>h.new_status===step).at(-1)?.created_at||''}
const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
function when(value?:string){if(!value)return '';const d=new Date(value);if(Number.isNaN(d.getTime()))return value;const clock=String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0');return locale.value==='zh'?`${d.getMonth()+1}月${d.getDate()}日 ${clock}`:`${d.getDate()} ${months[d.getMonth()]}, ${clock}`}
function reached(step:string){return stages.indexOf(order.value?.status||'')>=stages.indexOf(step)}
const blankPrice=(v:number|string)=>v===''||v==null||Number.isNaN(Number(v));
function nextStep(){if(quoteStep.value===1&&(!/^[A-Z]{3}$/.test(draft.currency)||!draft.valid_until)){error.value=tx('先填好币种和有效期','Enter the currency and valid-until date first');return}if(quoteStep.value===2&&draft.lines.some(l=>l.product_id===''||l.width===''||l.height===''||!l.material||!l.color||!l.control||!Number(l.quantity))){error.value=tx('产品明细还没填完','Finish the product details first');return}error.value='';quoteStep.value=Math.min(3,quoteStep.value+1)}
function start(i:Inquiry){draft.inquiry_id=i.id;draft.locale=i.locale;draft.lines=[fresh()];revision.value=null;assisted.value=false;draftGaps.value=[];quoteStep.value=1;editing.value=true;tab.value='quotes'}
function party(i:Inquiry){const customer=customers.value.find(c=>c.id===i.customer_id);const person=customer?.contacts[0];return {zh:(customer?customer.locale:i.locale)==='zh',name:person?.name||i.contact_name}}
function gaps(i:Inquiry){const zh=party(i).zh;const missing:string[]=[];if(!i.width||!i.height)missing.push(zh?'尺寸':'size');if(!i.expected_date)missing.push(zh?'交期':'timing');if(!i.product_id)missing.push(zh?'产品':'product');return missing}
function draftQuote(i:Inquiry){const zh=party(i).zh;draftGaps.value=gaps(i);draft.inquiry_id=i.id;draft.locale=zh?'zh':'en';draft.lines=[{product_id:i.product_id||'',width:i.width||'',height:i.height||'',unit:(i.unit==='inch'?'inch':'mm'),material:'',color:'',control:'',quantity:i.quantity||1,unit_price:''}];draft.terms=zh?'商务条款随本项目确认。':'Commercial terms to be confirmed with this project.';revision.value=null;assisted.value=true;quoteStep.value=1;editing.value=true;tab.value='quotes';message.value=tx('这是草稿，单价未填，保存前请人工确认','This is a draft. The unit price is blank. Confirm it before saving')}
async function assist(i:Inquiry){return request<{summary:string;reply:string;suggested_next_at:string;connected:boolean;mode:string}>(`inquiries/${i.id}/assistant`,{})}
async function summarize(i:Inquiry){await act(async()=>{const draft=await assist(i);if(draft.connected||draft.mode!=='rules')throw new Error(tx('只能使用规则助手','Only the rule assistant is available'));note.value=draft.summary;nextAt.value=draft.suggested_next_at;message.value=tx('这是摘要草稿和建议的跟进时间，点保存跟进才会记下，不会自动发出','This is a draft summary and a suggested follow-up time. It is recorded only when you click Save follow-up, and nothing is sent')})}
async function draftReply(i:Inquiry){await act(async()=>{const draft=await assist(i);if(draft.connected||draft.mode!=='rules')throw new Error(tx('只能使用规则助手','Only the rule assistant is available'));note.value=draft.reply;if(!nextAt.value)nextAt.value=draft.suggested_next_at;message.value=tx('回复还在草稿里，点保存跟进才会记下','The reply is still a draft. It is saved only when you click Save follow-up')})}
async function copyReply(){if(!note.value.trim()){message.value=tx('还没有回复草稿','There is no reply draft yet');return}try{await navigator.clipboard.writeText(note.value);message.value=tx('回复草稿已复制','Reply draft copied')}catch{error.value='';message.value=tx('复制没有成功，请在备注框里手动复制','Copy did not succeed. Select the note and copy it yourself')}}
function revise(v:Version){draft.inquiry_id=v.inquiry_id;draft.locale=v.locale;draft.currency=v.currency;draft.valid_until=v.valid_until;draft.discount=Number(v.discount);draft.shipping=Number(v.shipping);draft.tax=Number(v.tax);draft.terms=v.terms;draft.lines=v.lines.map(l=>({...l}));revision.value=v.quote_id;assisted.value=false;draftGaps.value=[];quoteStep.value=1;editing.value=true}
async function save(){await act(async()=>{if(draft.lines.some(l=>l.product_id===''))throw new Error(tx('产品还没选，草稿不能保存成报价','Choose a product before saving this draft as a quote'));if(draft.lines.some(l=>blankPrice(l.unit_price)))throw new Error(tx('单价还空着，草稿不能保存成报价','The unit price is still blank, so this draft cannot be saved as a quote'));const r=revision.value?await request<Version>(`quotes/${revision.value}/versions`,draft):await request<Quote>('quotes',draft);const id=revision.value||(r as Quote).id;await load();quote.value=quotes.value.find(q=>q.id===id)!;version.value=quote.value.versions.at(-1)!;editing.value=false;confirmationOpen.value=false;message.value=tx('报价已保存。下一步：发送给客户，按反馈修订或登记接受后生成订单。','Quote saved. Next: share it with the customer, revise it if needed, or record acceptance to create the order.')})}
async function exportVersion(lang:string){const win=window.open('about:blank','_blank');await act(async()=>{const v=version.value!;const html=await request<string>(`quotes/${v.quote_id}/versions/${v.version}/export?lang=${lang}`,undefined,true);if(!win)throw new Error(tx('请允许弹出窗口','Allow pop-up windows'));win.document.open();win.document.write(html);win.document.close()})}
async function accept(){await act(async()=>{const v=version.value!;const r=await request<Order>(`quotes/${v.quote_id}/versions/${v.version}/accept`,{note:confirmation.value});await load();order.value=orders.value.find(o=>o.id===r.id)!;confirmation.value='';confirmationOpen.value=false;tab.value='orders';message.value=tx('订单已确认，快照已冻结','Order confirmed, snapshot frozen')})}
const next=computed(()=>({confirmed:'production',production:'ready',ready:'delivered'} as Record<string,string>)[order.value?.status||'']);
async function advance(){await act(async()=>{await request(`orders/${order.value!.id}/status`,{status:next.value,note:tx('演示阶段更新','Demo stage update')});await load()})}
const quoteOrder=computed(()=>quote.value?.versions.map(v=>v.accepted_order_id).find(Boolean)||null);
const currentQuote=computed(()=>!!version.value&&version.value.version===quote.value?.versions.at(-1)?.version);
function relatedQuotes(id:number){return quotes.value.filter(q=>q.inquiry_id===id)}
function relatedOrders(id:number){return orders.value.filter(o=>o.snapshot.inquiry_id===id)}
function customerQuotes(id:number){const ids=new Set(inquiries.value.filter(i=>i.customer_id===id).map(i=>i.id));return quotes.value.filter(q=>ids.has(q.inquiry_id))}
function openQuote(q:Quote){quote.value=q;version.value=q.versions.at(-1)!;editing.value=false;confirmationOpen.value=false;confirmation.value='';tab.value='quotes'}
function openOrder(id:number){const found=orders.value.find(o=>o.id===id);if(found){order.value=found;editing.value=false;tab.value='orders'}}
function openInquiry(id:number){const found=inquiries.value.find(i=>i.id===id);if(found){selected.value=found;editing.value=false;tab.value='inquiries'}}
function ensureSelection(){if(tab.value==='customers'&&!customer.value&&visibleCustomers.value[0])openCustomer(visibleCustomers.value[0]);if(tab.value==='inquiries'&&!selected.value&&inquiries.value[0])selected.value=inquiries.value[0];if(tab.value==='quotes'&&!editing.value&&!quote.value&&quotes.value[0]){quote.value=quotes.value[0];version.value=quotes.value[0].versions.at(-1)||null}if(tab.value==='orders'&&!order.value&&orders.value[0])order.value=orders.value[0];if(tab.value==='products'&&!products.value.some(p=>p.id===catalog.value)&&products.value[0])catalog.value=products.value[0].id}
function openTab(key:string){tab.value=key;editing.value=false;ensureSelection()}
const flowHint=computed(()=>{const map:Record<string,[string,string]>={inquiries:['先看这条询价。规格齐了，再去做报价。','Read this inquiry. Quote it once the specifications are clear.'],quotes:['单价由人工填写。客户接受后，才变成订单。','A person enters the price. It becomes an order only after the customer accepts.'],orders:['新订单只从报价上的「生成订单」来，不手填，也不导入转账。','A new order comes only from Generate order on a quote. Nothing is typed in, and transfers are not imported.'],products:['左边选一条示例。这里不下单，也不标价。','Choose a sample on the left. Nothing is ordered or priced here.'],customers:['查看此客户的询价、报价与订单。','View this customer’s inquiries, quotations and orders.'],users:['管理员在这里添加销售账号。','An admin adds sales accounts here.']};return tx(...(map[tab.value]||map.inquiries))})
onMounted(()=>{if(signed.value)act(async()=>{await load();ensureSelection()})});
</script>
<template>
<main class="page crm" :class="{'is-signed':signed}"><aside v-if="signed" class="desk-rail"><div class="rail-brand">VERA</div><button v-for="(label,key) in {customers:tx('客户资料','Customers'),inquiries:tx('询价跟进','Inquiries'),quotes:tx('报价管理','Quotations'),orders:tx('订单交付','Order delivery')}" :key="key" :class="{current:tab===key}" @click="openTab(key)"><span class="rail-icon" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><template v-if="key==='customers'"><circle cx="8" cy="5" r="2.1"/><path d="M3.2 13.2v-.5a3.3 3.3 0 0 1 3.3-3.3h2.9a3.3 3.3 0 0 1 3.3 3.3v.5"/></template><template v-else-if="key==='inquiries'"><path d="M2.8 3.2h10.4v7.2H6.4L2.8 13z"/></template><template v-else-if="key==='quotes'"><path d="M4.2 2.4h5.1L12 5.1v8.5H4.2z"/><path d="M9.3 2.4v2.7H12M6.2 8h3.8M6.2 10.4h3.8"/></template><template v-else><path d="M2.6 5.4 8 2.6l5.4 2.8v5.2L8 13.4 2.6 10.6z"/><path d="M2.6 5.4 8 8.2l5.4-2.8M8 8.2v5.2"/></template></svg></span>{{label}}<span class="rail-count">{{key==='customers'?customers.length:key==='inquiries'?inquiries.length:key==='quotes'?quotes.length:orders.length}}</span></button><button :class="{current:tab==='products'}" @click="openTab('products')"><span class="rail-icon" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><rect x="2.5" y="2.5" width="11" height="11" rx="1"/><path d="M2.5 6.5h11M6.5 6.5V13.5"/></svg></span>{{tx('产品目录','Product catalogue')}}<span class="rail-count">{{products.length}}</span></button><button v-if="me.role==='admin'" :class="{current:tab==='users'}" @click="openTab('users')"><span class="rail-icon" aria-hidden="true"><svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"><circle cx="6" cy="5.2" r="1.9"/><path d="M2.3 12.8v-.3a2.7 2.7 0 0 1 2.7-2.7H7a2.7 2.7 0 0 1 2.7 2.7v.3"/><circle cx="11.3" cy="5.6" r="1.4"/><path d="M11 9.4h1a2.2 2.2 0 0 1 2.2 2.2v.5"/></svg></span>{{tx('用户与权限','Users & access')}}</button><div class="rail-bottom"><span class="user-avatar">{{(me.name||'V').slice(0,1)}}</span><div class="user-meta"><strong>{{me.name}}</strong><small>{{me.role==='admin'?tx('管理员','Admin'):tx('销售','Sales')}}</small></div></div></aside><header v-if="!signed" class="heading"><div><p class="eyebrow">VERA</p><h1>{{tx('内部登录','Internal sign in')}}</h1><p>{{tx('客户资料仅对已登录用户开放','Customer information requires sign in')}}</p></div></header>
<p v-if="error" class="alert" role="alert">{{error}}</p><p v-if="message" class="success" role="status">{{message}}</p>
<form v-if="!signed" class="card login" @submit.prevent="login"><h2>{{tx('内部登录','Internal sign in')}}</h2><p>{{tx('客户资料仅对已登录用户开放','Customer information requires sign in')}}</p><label>{{tx('用户名','Username')}}<input v-model="credentials.username" autocomplete="username" required /></label><label>{{tx('密码','Password')}}<input v-model="credentials.password" type="password" autocomplete="current-password" required /></label><button :disabled="busy">{{tx('登录','Sign in')}}</button></form>
<template v-else><header class="crm-bar"><span>{{me.name}} · {{me.role==='admin'?tx('管理员','Admin'):tx('销售','Sales')}}</span><button type="button" class="secondary" @click="toggleLocale">{{locale==='zh'?'English':'中文'}}</button><button type="button" class="secondary" @click="passwordOpen=!passwordOpen">{{tx('修改密码','Change password')}}</button><button type="button" class="secondary" @click="logout">{{tx('退出','Sign out')}}</button></header><form v-if="passwordOpen" class="password-form" @submit.prevent="changePassword"><label>{{tx('当前密码','Current password')}}<input v-model="passwordForm.current" type="password" autocomplete="current-password" required /></label><label>{{tx('新密码','New password')}}<input v-model="passwordForm.next" type="password" autocomplete="new-password" minlength="8" required /></label><label>{{tx('再输入一次','Repeat the new password')}}<input v-model="passwordForm.confirm" type="password" autocomplete="new-password" minlength="8" required /></label><button :disabled="busy">{{tx('保存密码','Save password')}}</button></form><div class="metrics"><article><span>{{tx('询价','Inquiries')}}</span><strong>{{inquiries.length}}</strong></article><article><span>{{tx('待处理','To handle')}}</span><strong>{{inquiries.filter(i=>i.status==='new'||i.status==='contacted').length}}</strong></article><article><span>{{tx('报价','Quotes')}}</span><strong>{{quotes.length}}</strong></article><article><span>{{tx('在途订单','Active orders')}}</span><strong>{{orders.filter(o=>o.status!=='delivered').length}}</strong></article></div>
<nav class="flow" :aria-label="tx('销售路径','Sales path')"><button type="button" :class="{current:tab==='inquiries'}" @click="openTab('inquiries')">1 {{tx('询价','Inquiry')}}</button><span aria-hidden="true">→</span><button type="button" :class="{current:tab==='quotes'}" @click="openTab('quotes')">2 {{tx('报价','Quote')}}</button><span aria-hidden="true">→</span><button type="button" :class="{current:tab==='orders'}" @click="openTab('orders')">3 {{tx('订单','Order')}}</button><p>{{flowHint}}</p></nav>
<div v-if="tab==='customers'" class="workspace"><aside class="card"><h2>{{tx('客户','Customers')}}</h2><label>{{tx('搜索客户','Search customers')}}<input v-model="customerQuery" type="search" @input="listPage.customers=1" /></label><p v-if="!customers.length">{{tx('官网询价后会出现客户资料','Customers appear after a website inquiry')}}</p><p v-else-if="!visibleCustomers.length">{{tx('没有匹配的客户','No matching customers')}}</p><button v-for="c in rows(visibleCustomers, 'customers')" :key="c.id" class="item" :class="{current:customer?.id===c.id}" @click="openCustomer(c)"><strong>{{c.company}}</strong><span>#{{c.id}} · {{c.contacts.length}} {{tx('位联系人','contacts')}}</span></button><nav class="pager" v-if="pageCount(visibleCustomers.length)>1"><button type="button" class="secondary" :disabled="listPage.customers<=1" @click="listPage.customers--">{{tx('上一页','Previous')}}</button><span>{{Math.min(listPage.customers,pageCount(visibleCustomers.length))}} / {{pageCount(visibleCustomers.length)}}</span><button type="button" class="secondary" :disabled="listPage.customers>=pageCount(visibleCustomers.length)" @click="listPage.customers++">{{tx('下一页','Next')}}</button></nav></aside><section class="card" v-if="customer"><h2>{{customer.company}}</h2><form @submit.prevent="saveCustomer"><div class="grid"><label>{{tx('公司','Company')}}<input v-model="profile.company" required /></label><label>{{tx('联系人','Contact')}}<input v-model="profile.contact_name" required /></label><label>{{tx('联系方式','Contact method')}}<input v-model="profile.channel" required /></label><label>{{tx('偏好语言','Preferred language')}}<select v-model="profile.locale"><option value="zh">中文</option><option value="en">English</option></select></label></div><label>{{tx('备注','Notes')}}<textarea v-model="profile.notes" /></label><button :disabled="busy">{{tx('保存修改','Save changes')}}</button></form><details class="fold"><summary>{{tx('联系人','Contacts')}} · {{customer.contacts.length}}</summary><article v-for="person in customer.contacts" :key="person.id" class="activity"><strong>{{person.name}}</strong><p>{{person.channel}}</p></article></details><details class="fold"><summary>{{tx('相关询价','Related inquiries')}} · {{customer.inquiries.length}}</summary><p v-if="!customer.inquiries.length">{{tx('还没有询价','No inquiries yet')}}</p><article v-for="item in customer.inquiries" :key="item.id" class="activity"><button type="button" class="record-link secondary" @click="openInquiry(item.id)">#{{item.id}} · {{item.contact_name}} ↗</button><small>{{status(item.status)}} · {{when(item.created_at)}}</small></article></details><details class="fold"><summary>{{tx('相关报价','Related quotes')}} · {{customerQuotes(customer.id).length}}</summary><button v-for="q in customerQuotes(customer.id)" :key="q.id" type="button" class="record-link secondary" @click="openQuote(q)">Q-{{q.id}} · {{q.versions.at(-1)?.currency}} {{q.versions.at(-1)?.total}} ↗</button></details><details class="fold"><summary>{{tx('相关订单','Related orders')}} · {{customer.orders.length}}</summary><p v-if="!customer.orders.length">{{tx('还没有订单','No orders yet')}}</p><article v-for="item in customer.orders" :key="item.id" class="activity"><button type="button" class="record-link secondary" @click="openOrder(item.id)">#{{item.id}} ↗</button><small>{{status(item.status)}} · {{when(item.created_at)}}</small></article></details></section><section class="card" v-else>{{tx('选择客户查看资料','Select a customer to view their details')}}</section></div>
<div v-if="tab==='inquiries'" class="workspace"><aside class="card"><h2>{{tx('客户询价','Trade inquiries')}}</h2><p v-if="!inquiries.length">{{tx('请先从官网提交询价','Submit an inquiry on the website to begin')}}</p><button v-for="i in rows(inquiries, 'inquiries')" :key="i.id" class="item" :class="{current:selected?.id===i.id}" @click="selected=i"><strong>{{i.company}}</strong><span>#{{i.id}} · {{i.contact_name}} · {{status(i.status)}}</span></button><nav class="pager" v-if="pageCount(inquiries.length)>1"><button type="button" class="secondary" :disabled="listPage.inquiries<=1" @click="listPage.inquiries--">{{tx('上一页','Previous')}}</button><span>{{Math.min(listPage.inquiries,pageCount(inquiries.length))}} / {{pageCount(inquiries.length)}}</span><button type="button" class="secondary" :disabled="listPage.inquiries>=pageCount(inquiries.length)" @click="listPage.inquiries++">{{tx('下一页','Next')}}</button></nav></aside><section class="card" v-if="selected"><h2>{{selected.company}}</h2><p>{{selected.contact_name}} · {{selected.channel}}</p><span class="badge">{{status(selected.status)}}</span><p class="inquiry-notes">{{selected.notes}}</p><div class="project-path" :aria-label="tx('当前项目进度','Current project progress')"><span class="path-done">{{tx('询价已收到','Inquiry received')}}</span><span aria-hidden="true">→</span><span :class="{'path-done':relatedQuotes(selected.id).length}">{{relatedQuotes(selected.id).length?tx('已有报价','Quote prepared'):tx('等待报价','Awaiting quote')}}</span><span aria-hidden="true">→</span><span :class="{'path-done':relatedOrders(selected.id).length}">{{relatedOrders(selected.id).length?tx('已生成订单','Order created'):tx('客户确认后生成订单','Order after acceptance')}}</span></div><div class="related-actions"><button v-for="q in relatedQuotes(selected.id)" :key="q.id" type="button" class="secondary" @click="openQuote(q)">{{tx('查看报价','View quote')}} Q-{{q.id}} ↗</button><button v-for="o in relatedOrders(selected.id)" :key="o.id" type="button" class="secondary" @click="openOrder(o.id)">{{tx('查看订单','View order')}} #{{o.id}} ↗</button></div><div class="action-row"><button :disabled="busy" @click="start(selected)">{{tx('创建人工报价','Create manual quote')}}</button><button type="button" class="secondary" @click="draftQuote(selected)">{{tx('整理报价草稿','Draft a quote')}}</button><button type="button" class="secondary" @click="summarize(selected)">{{tx('整理沟通摘要','Summarize the conversation')}}</button><button type="button" class="secondary" @click="draftReply(selected)">{{tx('生成回复草稿','Draft a reply')}}</button><button type="button" class="secondary" @click="copyReply">{{tx('复制回复草稿','Copy reply draft')}}</button></div><p class="badge">{{tx('规则助手 · 外部 AI 未连接 · 人工确认','Rule assistant · External AI is not connected · Confirm by a person')}}</p><form class="follow-form" @submit.prevent="follow"><label>{{tx('本次沟通','Conversation note')}}<textarea v-model="note" required /></label><label>{{tx('下次跟进时间','Next follow-up')}}<input v-model="nextAt" type="datetime-local" /></label><button :disabled="busy">{{tx('保存跟进','Save follow-up')}}</button></form><details v-if="selected.followups.length" class="fold"><summary>{{tx('跟进记录','Follow-up activity')}} · {{selected.followups.length}}</summary><article v-for="f in selected.followups" :key="f.id" class="activity"><p>{{f.note}}</p><small>{{when(f.created_at)}}<br/>{{tx('下次','Next')}}: {{when(f.next_at)||'—'}}</small></article></details></section><section class="card" v-else>{{tx('选择询价查看客户资料','Select an inquiry to view customer details')}}</section></div>
<div v-if="tab==='quotes'" class="workspace"><aside class="card"><h2>{{tx('报价管理','Quotations')}}</h2><p v-if="!quotes.length">{{tx('从询价详情创建第一份报价','Create a quote from an inquiry')}}</p><button v-for="q in rows(quotes, 'quotes')" :key="q.id" class="item" :class="{current:quote?.id===q.id}" @click="openQuote(q)"><strong>Q-{{q.id}} · {{inquiries.find(i=>i.id===q.inquiry_id)?.company}}</strong><span>{{q.versions.length}} {{tx('个版本','versions')}} · {{q.versions.at(-1)?.currency}} {{q.versions.at(-1)?.total}}</span></button><nav class="pager" v-if="pageCount(quotes.length)>1"><button type="button" class="secondary" :disabled="listPage.quotes<=1" @click="listPage.quotes--">{{tx('上一页','Previous')}}</button><span>{{Math.min(listPage.quotes,pageCount(quotes.length))}} / {{pageCount(quotes.length)}}</span><button type="button" class="secondary" :disabled="listPage.quotes>=pageCount(quotes.length)" @click="listPage.quotes++">{{tx('下一页','Next')}}</button></nav></aside><section class="card">
<form v-if="editing" @submit.prevent="quoteStep===3?save():nextStep()"><h2>{{revision?tx('创建修订版本','Create revision'):assisted?tx('报价草稿','Quote draft'):tx('创建报价 v1','Create quote v1')}}</h2><div class="quote-steps"><button type="button" :class="{chosen:quoteStep===1}" @click="quoteStep=1">1 {{tx('条件','Terms')}}</button><button type="button" :class="{chosen:quoteStep===2}" @click="quoteStep=2">2 {{tx('产品明细','Product details')}}</button><button type="button" :class="{chosen:quoteStep===3}" @click="quoteStep=3">3 {{tx('金额','Amounts')}}</button></div><div v-show="quoteStep===1"><p v-if="assisted" class="badge">{{tx('规则助手，外部 AI 未连接。草稿需人工确认，单价留空。','Rule assistant. External AI is not connected. Confirm this draft. The unit price stays blank.')}}</p><aside v-if="assisted" class="activity"><strong>{{tx('待人工补齐','Still to confirm')}}</strong><p v-if="!draftGaps.length">{{tx('规格已齐，单价仍由人工填写。','The specifications are complete. A person still enters the unit price.')}}</p><ul v-else><li v-for="gap in draftGaps" :key="gap">{{gap}}</li></ul></aside><div class="grid"><label>{{tx('报价语言','Quote language')}}<select v-model="draft.locale"><option value="zh">中文</option><option value="en">English</option></select></label><label>{{tx('币种（演示）','Currency (demo)')}}<input v-model="draft.currency" pattern="[A-Z]{3}" maxlength="3" required /></label><label>{{tx('有效期','Valid until')}}<input v-model="draft.valid_until" type="date" required /></label></div></div><div v-show="quoteStep===2">
<fieldset v-for="(l,index) in draft.lines" :key="index"><legend>{{tx('产品明细','Product details')}} {{index+1}}</legend><div class="grid"><label>{{tx('产品','Product')}}<select v-model="l.product_id" required><option value="">{{tx('选择产品','Choose a product')}}</option><option v-for="p in products" :key="p.id" :value="p.id">{{locale==='zh'?p.name_zh:p.name_en}}</option></select></label><label>{{tx('宽度','Width')}}<input v-model.number="l.width" type="number" min="0.01" step="any" required /></label><label>{{tx('高度','Drop')}}<input v-model.number="l.height" type="number" min="0.01" step="any" required /></label><label>{{tx('单位','Unit')}}<select v-model="l.unit"><option>mm</option><option>inch</option></select></label><label>{{tx('材质','Material')}}<input v-model="l.material" required /></label><label>{{tx('颜色','Colour')}}<input v-model="l.color" required /></label><label>{{tx('控制方式','Control')}}<input v-model="l.control" required /></label><label>{{tx('数量','Quantity')}}<input v-model.number="l.quantity" type="number" min="1" step="1" required /></label><label>{{tx('人工单价','Manual unit price')}}<input v-model.number="l.unit_price" type="number" min="0" step="0.01" required /></label></div><button v-if="draft.lines.length>1" class="secondary" type="button" @click="draft.lines.splice(index,1)">{{tx('移除此行','Remove line')}}</button></fieldset>
<button class="secondary" type="button" @click="draft.lines.push(assisted?{...fresh(),product_id:'',material:'',color:'',control:'',width:'',height:'',unit_price:''}:fresh())">{{tx('添加产品','Add product')}}</button></div><div v-show="quoteStep===3"><div class="grid"><label>{{tx('折扣','Discount')}}<input v-model.number="draft.discount" type="number" min="0" step="0.01" required /></label><label>{{tx('运费','Shipping')}}<input v-model.number="draft.shipping" type="number" min="0" step="0.01" required /></label><label>{{tx('税额','Tax amount')}}<input v-model.number="draft.tax" type="number" min="0" step="0.01" required /></label></div><label>{{tx('条款','Terms')}}<textarea v-model="draft.terms" /></label><p class="total">{{draft.lines.some(l=>blankPrice(l.unit_price))?tx('单价待填写','Unit price not entered'):draft.currency+' '+total.toFixed(2)}}</p></div><div class="tabs"><button v-if="quoteStep>1" type="button" class="secondary" @click="quoteStep--">{{tx('上一步','Back')}}</button><button v-if="quoteStep<3" type="button" @click="nextStep">{{tx('下一步','Next')}}</button><button v-else :disabled="busy">{{tx('保存不可变版本','Save immutable version')}}</button><button type="button" class="secondary" @click="editing=false">{{tx('取消','Cancel')}}</button></div></form>
<template v-else-if="quote&&version"><div class="quote-next"><div><span class="section-label">{{tx('下一步','NEXT STEP')}}</span><h3>{{quoteOrder?tx('此报价已生成订单','Order created from this quote'):!currentQuote?tx('历史版本，仅供查看','Historical version for reference'):tx('等待客户确认报价','Awaiting customer acceptance')}}</h3><p>{{quoteOrder?tx('查看对应订单，继续安排生产和交付。','Open the linked order to manage production and delivery.'):!currentQuote?tx('请选最新版本确认，避免按旧规格生成订单。','Choose the latest version to avoid ordering outdated specifications.'):tx('客户要求调整时先修订报价；客户已接受时登记确认依据，再生成订单。','Revise the quote if the customer requests changes. When accepted, record the evidence and create the order.')}}</p></div><div class="related-actions"><button v-if="quoteOrder" type="button" @click="openOrder(quoteOrder)">{{tx('查看订单','View order')}} #{{quoteOrder}} ↗</button><template v-else-if="currentQuote"><button type="button" class="secondary" @click="revise(version)">{{tx('客户要求调整 · 修订报价','Changes requested · Revise quote')}}</button><button type="button" :aria-expanded="confirmationOpen" aria-controls="quote-acceptance" @click="confirmationOpen=!confirmationOpen">{{tx('客户已接受 · 生成订单','Customer accepted · Create order')}}</button></template></div><form v-if="confirmationOpen&&currentQuote&&!quoteOrder" id="quote-acceptance" class="acceptance-form" @submit.prevent="accept"><p><strong>Q-{{quote.id}} / v{{version.version}}</strong> · {{inquiries.find(i=>i.id===quote!.inquiry_id)?.company}} · <strong>{{version.currency}} {{version.total}}</strong></p><label>{{tx('客户确认依据','Customer acceptance evidence')}}<textarea v-model="confirmation" required maxlength="4000" :placeholder="tx('例如：客户邮件确认接受此版本，日期与联系人。','For example: customer email accepting this version, with date and contact.')" /></label><p class="hint">{{tx('确认后保存此版本的规格与金额为订单快照。后续修订不改变已生成的订单。','This version’s specifications and amount are frozen in the order. Later revisions do not change it.')}}</p><div class="related-actions"><button :disabled="busy||!confirmation.trim()">{{tx('登记确认并生成订单','Record acceptance and create order')}}</button><button type="button" class="secondary" @click="confirmationOpen=false">{{tx('暂不生成','Not yet')}}</button></div></form></div><h2>Q-{{quote.id}} / v{{version.version}}</h2><div class="tabs"><button v-for="v in quote.versions" :key="v.version" class="secondary" :class="{chosen:version.version===v.version}" @click="version=v">v{{v.version}}</button></div><p>{{tx('版本保存后不可覆盖','Saved versions cannot be overwritten')}} · {{tx('有效期','Valid until')}} {{version.valid_until}}</p><div class="table-wrap"><table><thead><tr><th>{{tx('产品与规格','Product & specifications')}}</th><th>{{tx('数量','Qty')}}</th><th>{{tx('单价','Price')}}</th><th>{{tx('金额','Amount')}}</th></tr></thead><tbody><tr v-for="(l,index) in version.lines" :key="index"><td>{{locale==='zh'?l.product?.name_zh:l.product?.name_en}}<small>{{l.width}} × {{l.height}} {{l.unit}}<br/>{{l.material}} / {{l.color}} / {{l.control}}</small></td><td>{{l.quantity}}</td><td>{{l.unit_price}}</td><td>{{l.amount}}</td></tr></tbody></table></div><p>{{tx('小计 / 折扣 / 运费 / 税额','Subtotal / discount / shipping / tax')}}: {{version.subtotal}} / {{version.discount}} / {{version.shipping}} / {{version.tax}}</p><p class="total">{{version.currency}} {{version.total}}</p><p>{{version.terms}}</p><div class="tabs"><button class="secondary" :disabled="busy" @click="exportVersion('zh')">{{tx('中文导出','Chinese export')}}</button><button class="secondary" :disabled="busy" @click="exportVersion('en')">{{tx('英文导出','English export')}}</button><button :disabled="busy" @click="revise(version)">{{tx('修订为新版本','Revise as new version')}}</button></div></template><p v-else>{{tx('选择报价或从询价新建','Select a quote or create one from an inquiry')}}</p>
</section></div>
<div v-if="tab==='orders'" class="workspace"><aside class="card"><h2>{{tx('订单','Orders')}}</h2><p>{{tx('新订单只从报价生成。这里不手填，也不导入转账。','A new order comes only from a quote. Nothing is typed in here, and transfers are not imported.')}}</p><p v-if="!orders.length">{{tx('还没有订单。先在报价里点生成订单。','No orders yet. Generate one from a quote.')}}</p><button v-for="o in rows(orders, 'orders')" :key="o.id" class="item" :class="{current:order?.id===o.id}" @click="order=o"><strong>#{{o.id}} · {{o.snapshot.customer.company}}</strong><span>{{status(o.status)}} · {{o.snapshot.currency}} {{o.snapshot.total}}</span></button><nav class="pager" v-if="pageCount(orders.length)>1"><button type="button" class="secondary" :disabled="listPage.orders<=1" @click="listPage.orders--">{{tx('上一页','Previous')}}</button><span>{{Math.min(listPage.orders,pageCount(orders.length))}} / {{pageCount(orders.length)}}</span><button type="button" class="secondary" :disabled="listPage.orders>=pageCount(orders.length)" @click="listPage.orders++">{{tx('下一页','Next')}}</button></nav></aside><section v-if="order" class="card"><h2>{{tx('订单','Order')}} #{{order.id}}</h2><span class="badge">{{status(order.status)}}</span><ol class="progress"><li v-for="step in stages" :key="step" :class="{reached:reached(step),current:order.status===step}"><span>{{status(step)}}</span><small v-if="order.status===step">{{tx('当前进度','Current step')}}</small><small v-else>{{when(stageTime(step))||tx('未到','Not yet')}}</small></li></ol><p>{{tx('已冻结报价快照','Frozen quote snapshot')}} Q-{{order.snapshot.quote_id}} / v{{order.snapshot.version}}</p><p>{{order.snapshot.customer.company}} · {{order.snapshot.customer.contact_name}}</p><p>{{order.snapshot.confirmation_note}}</p><ul><li v-for="(l,index) in order.snapshot.lines" :key="index">{{locale==='zh'?l.product?.name_zh:l.product?.name_en}} · {{l.width}} × {{l.height}} {{l.unit}} · {{l.material}} / {{l.color}} / {{l.control}} · {{l.quantity}} × {{l.unit_price}}</li></ul><p class="total">{{order.snapshot.currency}} {{order.snapshot.total}}</p><button v-if="next" :disabled="busy" @click="advance">{{tx('推进到','Advance to')}} {{status(next)}}</button><p>{{tx('当前','Now')}}: {{status(order.status)}}</p><p v-if="order.history.length>1">{{tx('上一步','Previous step')}}: {{status(order.history.at(-2)!.new_status)}} · {{when(order.history.at(-2)!.created_at)}}</p><p v-else>{{tx('还没有上一步','No earlier step')}}</p><details class="fold"><summary>{{tx('状态履历','Status history')}} · {{order.history.length}}</summary><article v-for="(h,index) in order.history" :key="index" class="activity"><strong>{{h.old_status?status(h.old_status)+' → ':''}}{{status(h.new_status)}}</strong><small>{{when(h.created_at)}}</small><p>{{h.note}}</p></article></details></section><section v-else class="card">{{tx('选择订单查看快照和交付阶段','Select an order to view its snapshot and delivery stages')}}</section></div>
<ProductManager v-if="tab==='products'" :admin="me.role==='admin'" @updated="act(load)" />
<div v-if="tab==='users'&&me.role==='admin'" class="workspace users-board"><section class="card"><h2>{{tx('用户与权限','Users & access')}}</h2><form class="user-form" @submit.prevent="addUser"><label>{{tx('用户名','Username')}}<input v-model="newUser.username" required pattern="[a-z0-9._-]{2,40}" autocomplete="off" /></label><label>{{tx('姓名','Name')}}<input v-model="newUser.name" required autocomplete="off" /></label><label>{{tx('初始密码','Starting password')}}<input v-model="newUser.password" type="password" minlength="8" required autocomplete="new-password" /></label><label>{{tx('权限','Access')}}<select v-model="newUser.role"><option value="staff">{{tx('销售','Sales')}}</option><option value="admin">{{tx('管理员','Admin')}}</option></select></label><button :disabled="busy">{{tx('添加用户','Add user')}}</button></form><div class="table-wrap"><table><thead><tr><th>{{tx('用户名','Username')}}</th><th>{{tx('姓名','Name')}}</th><th>{{tx('权限','Access')}}</th></tr></thead><tbody><tr v-for="person in users" :key="person.username"><td>{{person.username}}</td><td>{{person.name}}</td><td><select :value="person.role" @change="onRole(person.username, $event)"><option value="admin">{{tx('管理员','Admin')}}</option><option value="staff">{{tx('销售','Sales')}}</option></select></td></tr></tbody></table></div></section></div></template></main>
</template>
<style scoped>
:global(.frame-work > .rail){display:none}
:global(.shell:has(.crm)){max-width:none;padding:0;background:var(--paper,#F4F7F5)}
:global(.shell:has(.crm) .topbar){padding:14px 28px;margin:0;border-bottom:1px solid var(--line,rgba(27,36,33,.14));background:white}
:global(.shell:has(.crm) .footer){padding:20px 28px;margin:0;background:white}
